mapper.select:
select c.id, c.post_id, c.member_id, c.content, c.del_flag, c.create_time, m.nickname as nickname, m.avatar as avatar from club_post_comment c left join ums_member m on m.id = c.member_id
c.del_flag = 0 and c.post_id = #{postId}
order by c.id asc

mapper.update:
update club_post_comment
del_flag = #{delFlag}, content = #{content}, like_count = #{likeCount},
where id = #{id}
